from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential
import os

def extract_document_layout(document_path: str) -> dict:
    """
    Extracts layout elements (blocks, lines, tables, etc.) from a document using Azure Document Intelligence.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(document_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-layout", AnalyzeDocumentRequest(bytes_data=f.read())
        )
        result = poller.result()

    layout_data = {
        "content": result.content,
        "pages": [],
        "paragraphs": [],
        "tables": [],
        "key_value_pairs": [],
        "styles": [],
    }

    if result.pages:
        for page in result.pages:
            layout_data["pages"].append(
                {
                    "page_number": page.page_number,
                    "width": page.width,
                    "height": page.height,
                    "unit": page.unit,
                    "lines": [
                        {
                            "content": line.content,
                            "bounding_regions": [
                                {"x": p.x, "y": p.y} for region in line.bounding_regions for p in region.polygon
                            ],
                        }
                        for line in page.lines
                    ]
                    if page.lines
                    else [],
                    "words": [
                        {
                            "content": word.content,
                            "confidence": word.confidence,
                            "bounding_regions": [
                                {"x": p.x, "y": p.y} for region in word.bounding_regions for p in region.polygon
                            ],
                        }
                        for word in page.words
                    ]
                    if page.words
                    else [],
                }
            )

    if result.paragraphs:
        for paragraph in result.paragraphs:
            layout_data["paragraphs"].append(
                {
                    "content": paragraph.content,
                    "role": paragraph.role,
                    "bounding_regions": [
                        {"x": p.x, "y": p.y} for region in paragraph.bounding_regions for p in region.polygon
                    ]
                    if paragraph.bounding_regions
                    else [],
                }
            )

    if result.tables:
        for table in result.tables:
            cells_data = []
            for cell in table.cells:
                cells_data.append(
                    {
                        "content": cell.content,
                        "row_index": cell.row_index,
                        "column_index": cell.column_index,
                        "row_span": cell.row_span,
                        "column_span": cell.column_span,
                        "is_header": cell.kind == "columnHeader",
                        "is_footer": cell.kind == "footer",
                        "bounding_regions": [
                            {"x": p.x, "y": p.y} for region in cell.bounding_regions for p in region.polygon
                        ]
                        if cell.bounding_regions
                        else [],
                    }
                )
            layout_data["tables"].append(
                {
                    "row_count": table.row_count,
                    "column_count": table.column_count,
                    "cells": cells_data,
                    "bounding_regions": [
                        {"x": p.x, "y": p.y} for region in table.bounding_regions for p in region.polygon
                    ]
                    if table.bounding_regions
                    else [],
                }
            )

    # Note: 'key_value_pairs' and 'styles' are more typically found in "prebuilt-document" or custom models.
    # The 'prebuilt-layout' model primarily focuses on structural elements like paragraphs, lines, words, and tables.
    # We include empty lists for completeness based on the prompt's request for "layout elements" which *could* include these
    # if a different model were used, but acknowledge 'prebuilt-layout' doesn't explicitly return them as top-level.
    # If using 'prebuilt-document', key_value_pairs would be in result.key_value_pairs and styles in result.styles.


    return layout_data
